async function parseIntent(userPrompt: string): Promise<ActionStep[]> {
  const response = await callLLM(INTENT_PROMPT + userPrompt);
  // Strip Markdown code fences the model adds even when asked not to, so the
  // remaining text is parseable JSON.
  const cleaned = response.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    // A bad plan aborts BEFORE any live API call; truncate so a runaway reply
    // doesn't flood the log but enough shows to diagnose.
    throw new Error(`Failed to parse intent: ${cleaned.slice(0, 200)}`);
  }
}

function resolveRefs(params: Record<string, any>, prevResults: any[]): Record<string, any> {
  const resolved: Record<string, any> = {};
  for (const [k, v] of Object.entries(params)) {
    // Only strings tagged with the $prev sentinel are rewritten; every literal
    // param passes straight through.
    if (typeof v === 'string' && v.startsWith('$prev')) {
      if (v === '$prev.conversationId') {
        const last = prevResults[prevResults.length - 1];   // most-recent result
        // Tolerate API shape drift: conversationId first, then id; empty string
        // (not undefined) if neither exists, so a bad ref fails as a clear API
        // error downstream rather than an undefined crash.
        resolved[k] = last?.conversationId || last?.id || '';
      } else {
        // ...match $prev.<index>.<field> and pull it from an earlier result
      }
    } else {
      resolved[k] = v;
    }
  }
  return resolved;
}

async function executeAction(api: AppApi, action: string, params: Record<string, any>): Promise<any> {
  switch (action) {   // closed allow-list — unknown verbs hit default and throw, never the API
    case 'create_conversation':
      return api.createConversation(params.name);
    case 'send_message':
      return api.sendMessage(params.conversationId, params.question, { service: params.model });
    case 'share_conversation': {
      const users = [];
      for (const u of params.users || []) {   // || [] tolerates a plan that omitted users
        const resolved = await api.resolveUser(u.name);   // name -> real account
        // Encode role numerically; anything other than 'edit' defaults to 0 (read-only),
        // so the SAFER permission wins when the role is unspecified/unknown.
        if (resolved) users.push({ ...resolved, role: u.role === 'edit' ? 1 : 0 });
      }
      // Never fire a share with an empty recipient list — fail loudly instead.
      if (users.length === 0) throw new Error('No users resolved for sharing');
      return api.shareConversation(params.conversationId, users);
    }
    // ...
    default:
      throw new Error(`Unknown action: ${action}`);   // hallucinated action name -> hard stop
  }
}

async resolveUser(exactName: string): Promise<{ userId: string; userName: string; userEmail: string } | null> {
  // Search on last name only (part before the first comma) so a 'Last, First'
  // input still returns candidates from a last-name-indexed directory...
  const searchTerm = exactName.split(',')[0].trim();
  const result = await this.searchUsers(searchTerm);
  // ...normalize the payload: array, or .value/.users wrapper depending on the API.
  const users = Array.isArray(result) ? result : (result.value || result.users || []);

  // PASS 1 — exact display-name equality wins, so 'John Smith' can't bind to
  // 'John Smithson' while the exact person is in the list.
  for (const u of users) {
    const name = u.displayName || u.userName || u.name || '';   // field name varies by API
    if (name === exactName) {
      return { userId: u.id || u.userId, userName: name, userEmail: u.email || u.mail || u.userEmail || '' };
    }
  }
  // PASS 2 — only if no exact match: case-insensitive contains, as a convenience.
  for (const u of users) {
    const name = u.displayName || u.userName || u.name || '';
    if (name.toLowerCase().includes(exactName.toLowerCase())) {
      return { userId: u.id || u.userId, userName: name, userEmail: u.email || u.mail || u.userEmail || '' };
    }
  }
  return null;   // no match -> null (never a guess), so the caller can refuse to share
}

function formatResult(action: string, result: any): string {
  if (!result) return '(empty response)';   // guard: some actions return nothing
  switch (action) {
    case 'create_conversation':
      return `Conversation created: ${result.id}`;
    case 'send_message':
      // || '' guards a missing answer; ?.length || 0 makes a null match read as
      // 0 words; slice(0,200) keeps a long reply from walling the terminal.
      return `Response (${(result.answer || '').match(/\S+/g)?.length || 0} words): ${(result.answer || '').slice(0, 200)}...`;
    case 'search_users': {
      const users = Array.isArray(result) ? result : (result.value || []);
      // Report the TRUE total but only print the first 10 rows.
      return `Found ${users.length} user(s):\n` + users.slice(0, 10).map((u) =>
        `  ${u.displayName || u.name} — ${u.mail || u.email || ''}`).join('\n');
    }
    default:
      // Safety net for any unrecognized action — bounded pretty-print, capped at 1000 chars.
      return JSON.stringify(result, null, 2).slice(0, 1000);
  }
}
